/**
* R2M11_AmpSettingsProfile8Bits_t
* RegisterName: AMP_SETTINGS_PROFILE8
* Transmitter amplitude monitor register : high & low levels
* a) content will be automatically updated by calibration engine, if selected by store_in_profile bit - RF_CAL_CTRL register
* b) this register can also be overridden by S/w if automatic calibration is not selected
* Address: 0x044
* ResetValue: 0x003C0C08
* Read/Write: RW
* FuSa: Y
*/
typedef struct  {
	/**
	* BitsName: Reserved_0 
	* Description: not used 
	*/
	uint32_t Reserved0 : 2;        /*## attribute Reserved0 */
	/**
	* BitsName: tx_power_target_mon_profile8
	* Description: value to be used as monitor input level_rf_high_spi_profile8 for output power calibration. 
	* Automatically  evaluated by calibration based on power target and monitor OTP anchor point 
	*  = MOD( tx_power_target_prolfile8 + TX_ANCHOR_POINT/anchor_point; 64)
	* Read/Write: RW
	* Bits: [29:24]
	* ResetValue: 0b000000
	* Source: Application
	* FuSa: Y
	*/
	uint32_t TxPowerTargetMonProfile8 : 6;        /*## attribute TxPowerTargetMonProfile8 */
	/**
	* BitsName: Reserved_1 
	* Description: not used 
	*/
	uint32_t Reserved1 : 2;        /*## attribute Reserved1 */
	/**
	* BitsName: tx_power_target_profile8
	* Description: 6 bit register to be used  as target for output power calibration, max = 15 dBm, 0.29 dB per LSB
	* default target 14.13 dBm
	* Read/Write: RW
	* Bits: [21:16]
	* ResetValue: 0b111100
	* Source: Application
	* FuSa: Y
	*/
	uint32_t TxPowerTargetProfile8 : 6;        /*## attribute TxPowerTargetProfile8 */
	/**
	* BitsName: Reserved_2 
	* Description: not used 
	*/
	uint32_t Reserved2 : 2;        /*## attribute Reserved2 */
	/**
	* BitsName: level_rf_high_spi_profile8
	* Description: High trigger level for Gain Control,  
	* V_thresh_high=0.9*10^(((level_rf_high_spi_profile8 - 63)*0.29)/20)
	* The value is updated by the calibration = tx_power_target_mon_profile8 + CAL_MON_LEVEL/level_rf_high_delta 
	* Read/Write: RW
	* Bits: [13:8]
	* ResetValue: 0b001100
	* Source: Application
	* FuSa: Y
	*/
	uint32_t LevelRfHighSpiProfile8 : 6;        /*## attribute LevelRfHighSpiProfile8 */
	/**
	* BitsName: Reserved_3 
	* Description: not used 
	*/
	uint32_t Reserved3 : 2;        /*## attribute Reserved3 */
	/**
	* BitsName: level_rf_low_spi_profile8
	* Description: Low trigger level for Gain Control,  
	* V_thresh_low=0.9*10^(((level_rf_low_spi_profile8 - 63)*0.29)/20)
	* The value is updated by the calibration = tx_power_target_mon_profile8 - CAL_MON_LEVEL/level_rf_low_delta 
	* Read/Write: RW
	* Bits: [5:0]
	* ResetValue: 0b001000
	* Source: Application
	* FuSa: Y
	*/
	uint32_t LevelRfLowSpiProfile8 : 6;        /*## attribute LevelRfLowSpiProfile8 */
}R2M11_AmpSettingsProfile8Bits_t;
